using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an invoice payment form. This method must be called when the user presses inline button of the type inlineKeyboardButtonTypeBuy, or wants to buy access to media in a messagePaidMedia message
    /// </summary>
    public Task<TdLib.TdApi.Objects.PaymentForm> GetPaymentFormAsync(InputInvoice inputInvoice = default, ThemeParameters theme = default)
    {

           using var activity =  StartCallActivity("GetPaymentFormAsync", typeof(GetPaymentForm).FullName ?? "GetPaymentFormAsync");

           try
           {
             return client.GetPaymentFormAsync(inputInvoice, theme);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
